		count(expectations, "MinCount", "minCount", "expected at least %s %s", "value", "values");
		count(expectations, "MaxCount", "maxCount", "expected at most %s %s", "value", "values");
		count(expectations, "MinLength", "minLength", "expected at least %s %s", "character", "characters");
