		fixed(expectations, "Property", "expected to conform to the property shape");
		fixed(expectations, "Not", "expected not to conform to the shape");
		fixed(expectations, "And", "expected to conform to all of the shapes");
		fixed(expectations, "Or", "expected to conform to at least one of the shapes");
		fixed(expectations, "Xone", "expected to conform to exactly one of the shapes");
